node -e "
const src=require('fs').readFileSync('lib/errors.js','utf8');
const defined=[...src.matchAll(/^  (FST_ERR_[A-Z_0-9]+): createError\(/gm)].map(m=>m[1]);
const t=require('fs').readFileSync('types/errors.d.ts','utf8');
const typed=[...t.matchAll(/'(FST_ERR_[A-Z_0-9]+)'/g)].map(m=>m[1]);
console.log('defined',defined.length,'typed',typed.length);
console.log('missing in types:', defined.filter(d=>!typed.includes(d)));
console.log('extra in types:', typed.filter(d=>!defined.includes(d)));
console.log('order differs:', JSON.stringify(defined.filter(d=>typed.includes(d))) === JSON.stringify(typed.filter(d=>defined.includes(d))) ? 'no':'yes');
"

