node -e "
const fs=require('fs');
const codes=Object.keys(require('./lib/errors.js').codes||require('./lib/errors.js'));
const typed=[...fs.readFileSync('types/errors.d.ts','utf8').matchAll(/'(FST_ERR_[A-Z_0-9]+)'/g)].map(m=>m[1]);
const tested=[...new Set([...fs.readFileSync('test/types/errors.test-d.ts','utf8').matchAll(/errorCodes\.(FST_ERR_[A-Z_0-9]+)/g)].map(m=>m[1]))];
const runtime=codes.filter(c=>c.startsWith('FST_ERR_'));
console.log('runtime exported:',runtime.length,'typed:',typed.length,'tested:',tested.length);
console.log('typed but not exported at runtime:',typed.filter(t=>!runtime.includes(t)));
console.log('exported but untyped:',runtime.filter(t=>!typed.includes(t)));
console.log('typed but untested:',typed.filter(t=>!tested.includes(t)));
"

